    s = _h_nfc(s).strip().lower().replace('đ', '').replace('₫', '')
    if not s or s in ('nan', 'none'):
        return np.nan
    s = s.replace(' ', '').replace(',', '')
    s = re.sub('[^0-9.\\-]', '', s)
    if s in ('', '-', '.'):
        return np.nan
    try:
        return float(s)
    except Exception:
        return np.nan

def _h_dates(col):
